/** Versioned Mac/Android envelope. Only standard platform JCE primitives. */
final class PortableVault {
    static final String SCHEMA="gendragoon.portable-vault/v1",KEYS="gendragoon.vault-keys/v1";
    static final int ITERATIONS=600000,MAX_KEYMAP=8*1024*1024,MAX_PLAIN=12*1024*1024,MAX_ENVELOPE=16*1024*1024;
    static final class Keys{final String receiver,secret;final byte[] keymap;Keys(String receiver,String secret,byte[] keymap){this.receiver=receiver;this.secret=secret;this.keymap=keymap;}}
    static void fields(JSONObject value,String...allowed)throws IOException{Set<String> keys=new HashSet<>(Arrays.asList(allowed));if(value.length()!=keys.size())throw new IOException("Unsupported vault fields.");Iterator<String> it=value.keys();while(it.hasNext())if(!keys.contains(it.next()))throw new IOException("Unsupported vault fields.");}
    static String encode(byte[] value){return Base64.getUrlEncoder().withoutPadding().encodeToString(value);}
    static byte[] decode(String value,int maximum)throws IOException{if(value==null||!value.matches("[A-Za-z0-9_-]+")||value.length()>((maximum+2)/3)*4)throw new IOException("Invalid portable vault encoding.");try{byte[] data=Base64.getUrlDecoder().decode(value);if(data.length>maximum||!encode(data).equals(value))throw new IOException("Noncanonical vault encoding.");return data;}catch(IllegalArgumentException e){throw new IOException("Invalid portable vault encoding.");}}
    static byte[] aad(String receiver)throws IOException{if(receiver==null||!receiver.matches("[a-f0-9]{64}"))throw new IOException("Invalid vault account identity.");return (SCHEMA+"\0"+receiver).getBytes(StandardCharsets.UTF_8);}
    static void passphrase(char[] password)throws IOException{String text=new String(password);if(text.codePointCount(0,text.length())<12||text.getBytes(StandardCharsets.UTF_8).length>1024)throw new IOException("Use a passphrase of at least 12 characters and at most 1024 UTF-8 bytes. Spaces are preserved.");}
    static byte[] crypt(int mode,byte[] data,char[] password,byte[] salt,byte[] nonce,String receiver)throws Exception{passphrase(password);PBEKeySpec spec=new PBEKeySpec(password,salt,ITERATIONS,256);byte[] key=null;try{key=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(mode,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));cipher.updateAAD(aad(receiver));return cipher.doFinal(data);}finally{spec.clearPassword();if(key!=null)Arrays.fill(key,(byte)0);}}
    static void keymap(byte[] value)throws IOException{if(value.length<11||value[0]!='K'||value[1]!='X'||value[2]!='A'||value[3]!='I')throw new IOException("This file does not contain a compatible private KXAI keymap.");int version=value[4]&255,want=version==1?75:version==2?87:version==3?95:0;if(want==0||value.length!=want)throw new IOException("Hardware-bound or unsupported keymaps cannot be imported as a portable vault.");int t=value[5]&255,p=value[6]&255;long memory=((long)(value[7]&255)<<24)|((long)(value[8]&255)<<16)|((long)(value[9]&255)<<8)|(value[10]&255);if(t<1||t>10||p<1||p>16||memory<8L*p||memory>256*1024)throw new IOException("This keymap exceeds the portable vault's supported Argon2 cost profile. No encryption parameters were downgraded.");}
    static Keys validate(JSONObject value,String expected)throws Exception{fields(value,"schema","receiverId","storageSecret","keymap");if(!KEYS.equals(value.getString("schema"))||!expected.equals(value.getString("receiverId")))throw new IOException("This vault belongs to a different Red-XAI account.");String secret=value.getString("storageSecret");if(!secret.matches("[A-Za-z0-9_-]{32,128}"))throw new IOException("Invalid portable vault storage credential.");byte[] keymap=decode(value.getString("keymap"),MAX_KEYMAP);keymap(keymap);return new Keys(expected,secret,keymap);}
    static Keys open(byte[] envelope,char[] password,String expected)throws Exception{if(envelope.length>MAX_ENVELOPE)throw new IOException("Portable vault exceeds 16 MiB.");JSONObject value=new JSONObject(new String(envelope,StandardCharsets.UTF_8));fields(value,"schema","receiverId","kdf","cipher","ciphertext");String receiver=value.getString("receiverId");if(!SCHEMA.equals(value.getString("schema"))||!expected.equals(receiver))throw new IOException("This vault belongs to a different Red-XAI account.");aad(receiver);JSONObject kdf=value.getJSONObject("kdf"),cipher=value.getJSONObject("cipher");fields(kdf,"name","iterations","salt");fields(cipher,"name","nonce");if(!"PBKDF2-HMAC-SHA256".equals(kdf.getString("name"))||!(kdf.get("iterations") instanceof Number)||kdf.getDouble("iterations")!=ITERATIONS||!"AES-256-GCM".equals(cipher.getString("name")))throw new IOException("Unsupported portable vault encryption parameters.");byte[] salt=decode(kdf.getString("salt"),16),nonce=decode(cipher.getString("nonce"),12),encrypted=decode(value.getString("ciphertext"),MAX_PLAIN+16);if(salt.length!=16||nonce.length!=12||encrypted.length<17)throw new IOException("Invalid portable vault encryption fields.");byte[] plain;try{plain=crypt(Cipher.DECRYPT_MODE,encrypted,password,salt,nonce,receiver);}catch(AEADBadTagException e){throw new IOException("The passphrase is incorrect or the portable vault was changed.");}try{if(plain.length>MAX_PLAIN)throw new IOException("Portable vault payload is too large.");return validate(new JSONObject(new String(plain,StandardCharsets.UTF_8)),expected);}finally{Arrays.fill(plain,(byte)0);}}
    static byte[] seal(Keys keys,char[] password)throws Exception{byte[] salt=new byte[16],nonce=new byte[12];SecureRandom random=new SecureRandom();random.nextBytes(salt);random.nextBytes(nonce);return seal(keys,password,salt,nonce);}
    static byte[] seal(Keys keys,char[] password,byte[] salt,byte[] nonce)throws Exception{JSONObject payload=new JSONObject().put("schema",KEYS).put("receiverId",keys.receiver).put("storageSecret",keys.secret).put("keymap",encode(keys.keymap));validate(payload,keys.receiver);byte[] plain=payload.toString().getBytes(StandardCharsets.UTF_8);try{if(plain.length>MAX_PLAIN||salt.length!=16||nonce.length!=12)throw new IOException("Portable vault payload is invalid.");byte[] encrypted=crypt(Cipher.ENCRYPT_MODE,plain,password,salt,nonce,keys.receiver);byte[] result=new JSONObject().put("schema",SCHEMA).put("receiverId",keys.receiver).put("kdf",new JSONObject().put("name","PBKDF2-HMAC-SHA256").put("iterations",ITERATIONS).put("salt",encode(salt))).put("cipher",new JSONObject().put("name","AES-256-GCM").put("nonce",encode(nonce))).put("ciphertext",encode(encrypted)).toString().getBytes(StandardCharsets.UTF_8);if(result.length>MAX_ENVELOPE)throw new IOException("Portable vault exceeds its size limit.");return result;}finally{Arrays.fill(plain,(byte)0);}}
}
